package edu.ankara.audiometer; import java.lang.reflect.*; import java.util.*;
public final class TestRunner { static final List<String> CLASSES=List.of("edu.ankara.audiometer.domain.algorithm.HughsonWestlakeEngineTest","edu.ankara.audiometer.domain.algorithm.ThresholdDetectorTest","edu.ankara.audiometer.domain.algorithm.ResponseReducerTest","edu.ankara.audiometer.domain.validation.AudiometryValidatorsTest","edu.ankara.audiometer.infrastructure.SerialProtocolTest","edu.ankara.audiometer.property.HughsonWestlakePropertiesTest","edu.ankara.audiometer.property.AudiometryStatePropertiesTest"); public static void main(String[] args) throws Exception{int pass=0; for(String c:CLASSES){Class<?> k=Class.forName(c); var ctor=k.getDeclaredConstructor(); ctor.setAccessible(true); Object o=ctor.newInstance(); for(Method m:o.getClass().getDeclaredMethods()){ if(m.isAnnotationPresent(org.junit.jupiter.api.Test.class)||m.isAnnotationPresent(net.jqwik.api.Example.class)||m.isAnnotationPresent(net.jqwik.api.Property.class)){ m.setAccessible(true); Object[] params=Arrays.stream(m.getParameterTypes()).map(TestRunner::sample).toArray(); m.invoke(o,params); pass++; }}} System.out.println("Custom unit/property tests passed: "+pass);} static Object sample(Class<?> t){ if(t==int.class)return 3; if(t==boolean.class)return true; if(t==String.class)return "invalid"; if(List.class.isAssignableFrom(t))return java.util.List.of(true,false,true); return null;} }
